func isTerminal(f *os.File) bool {
	st, err := f.Stat()
	if err != nil {
		return false
	}
	return (st.Mode() & os.ModeCharDevice) != 0
}

func errorPrefix() string {
	if isTerminal(os.Stderr) {
		return "[ \x1b[31;1mERROR\x1b[0;22m ] "
	}
	return "[ ERROR ] "
}

func printError(msg string) {
	fmt.Fprintln(os.Stderr, errorPrefix()+msg)
}

func parseArgs(args []string) parseResult {
	opts := options{count: 20}
	positional := []string{}
	stopOptions := false

	for i := 0; i < len(args); i++ {
		a := args[i]
		if stopOptions {
			positional = append(positional, a)
			continue
		}
		if a == "--" {
			stopOptions = true
			continue
		}
		if strings.HasPrefix(a, "--") && len(a) > 2 {
			nameval := a[2:]
			name := nameval
			value := ""
			hasEq := false
			if eq := strings.IndexByte(nameval, '='); eq >= 0 {
				name = nameval[:eq]
				value = nameval[eq+1:]
				hasEq = true
			}
			switch name {
			case "help":
				if hasEq {
					return parseResult{outcome: parseErr, err: "bool flag `-h, --help' cannot have an argument"}
				}
				return parseResult{outcome: parseHelp}
			case "version":
				if hasEq {
					return parseResult{outcome: parseErr, err: "bool flag `-V, --version' cannot have an argument"}
				}
				opts.version = true
			case "privilege":
				if hasEq {
					return parseResult{outcome: parseErr, err: "bool flag `-P, --privilege' cannot have an argument"}
				}
				opts.privileged = true
			case "count":
				if !hasEq {
					if i+1 >= len(args) {
						return parseResult{outcome: parseErr, err: "expected argument for flag `-c, --count'"}
					}
					if looksLikeOption(args[i+1]) {
						return parseResult{outcome: parseErr, err: fmt.Sprintf("expected argument for flag `-c, --count', but got option `%s'", args[i+1])}
					}
					i++
					value = args[i]
				}
				cnt, perr := parseCount(value)
				if perr != "" {
					return parseResult{outcome: parseErr, err: perr}
				}
				opts.count = cnt
			default:
				return parseResult{outcome: parseErr, err: fmt.Sprintf("unknown flag `%s'", name)}
			}
			continue
		}

		if strings.HasPrefix(a, "-") && a != "-" && len(a) > 1 {
			// Special short-option forms with an explicit = argument to a bool.
			if len(a) >= 3 && a[2] == '=' {
				switch a[1] {
				case 'h':
					return parseResult{outcome: parseErr, err: "bool flag `-h, --help' cannot have an argument"}
				case 'V':
					return parseResult{outcome: parseErr, err: "bool flag `-V, --version' cannot have an argument"}
				case 'P':
					return parseResult{outcome: parseErr, err: "bool flag `-P, --privilege' cannot have an argument"}
				case 'c':
					value := a[3:]
					cnt, perr := parseCount(value)
					if perr != "" {
						return parseResult{outcome: parseErr, err: perr}
					}
					opts.count = cnt
					continue
				}
			}

			// If -c is the first short flag, attached text is its value.
			if a[1] == 'c' {
				if len(a) > 2 {
					value := a[2:]
					cnt, perr := parseCount(value)
					if perr != "" {
						return parseResult{outcome: parseErr, err: perr}
					}
					opts.count = cnt
					continue
				}
				if i+1 >= len(args) {
					return parseResult{outcome: parseErr, err: "expected argument for flag `-c, --count'"}
				}
				if looksLikeOption(args[i+1]) {
					return parseResult{outcome: parseErr, err: fmt.Sprintf("expected argument for flag `-c, --count', but got option `%s'", args[i+1])}
				}
				i++
				cnt, perr := parseCount(args[i])
				if perr != "" {
					return parseResult{outcome: parseErr, err: perr}
				}
				opts.count = cnt
				continue
			}

			// Remaining short options are a cluster. If c appears at the end,
			// it consumes the next argument; if text trails it, go-flags reports
			// a missing argument for c.
			for j := 1; j < len(a); j++ {
				switch a[j] {
				case 'h':
					return parseResult{outcome: parseHelp}
				case 'V':
					opts.version = true
				case 'P':
					opts.privileged = true
				case 'c':
					if j != len(a)-1 {
						return parseResult{outcome: parseErr, err: "expected argument for flag `-c, --count'"}
					}
					if i+1 >= len(args) {
						return parseResult{outcome: parseErr, err: "expected argument for flag `-c, --count'"}
					}
					if looksLikeOption(args[i+1]) {
						return parseResult{outcome: parseErr, err: fmt.Sprintf("expected argument for flag `-c, --count', but got option `%s'", args[i+1])}
					}
					i++
					cnt, perr := parseCount(args[i])
					if perr != "" {
						return parseResult{outcome: parseErr, err: perr}
					}
					opts.count = cnt
					j = len(a)
				default:
					return parseResult{outcome: parseErr, err: fmt.Sprintf("unknown flag `%c'", a[j])}
				}
			}
			continue
		}

		positional = append(positional, a)
	}

	if opts.version {
		return parseResult{outcome: parseVersion}
	}
	opts.args = positional
	return parseResult{outcome: parseOK, opts: opts}
}

func looksLikeOption(s string) bool {
	if len(s) < 2 || s[0] != '-' {
		return false
	}
	// Numeric negative values are valid arguments for -c.
	if s[1] >= '0' && s[1] <= '9' {
		return false
	}
	return true
}

func parseCount(s string) (int, string) {
	v, err := strconv.ParseInt(s, 10, 0)
	if err != nil {
		return 0, fmt.Sprintf("invalid argument for flag `-c, --count' (expected int): %s", err.Error())
	}
	return int(v), ""
}

type runner struct {
	host       string
	ipaddr     *net.IPAddr
	count      int
	privileged bool
	stdoutTTY  bool
	packetsSent int
	packetsRecv int
	rtts       []time.Duration
}

func newRunner(host string, ipaddr *net.IPAddr, count int, priv bool) *runner {
	return &runner{host: host, ipaddr: ipaddr, count: count, privileged: priv, stdoutTTY: isTerminal(os.Stdout)}
}

func (r *runner) run() error {
	r.printHeader()
	if r.privileged {
		return r.runPrivileged()
	}
	return r.runUnprivileged()
}

func (r *runner) printHeader() {
	if r.stdoutTTY {
		fmt.Fprintf(os.Stdout, "\x1b[97;1mPING %s (%s) type `Ctrl-C` to abort\n\x1b[0m", r.host, r.ipaddr.String())
	} else {
		fmt.Fprintf(os.Stdout, "PING %s (%s) type `Ctrl-C` to abort\n", r.host, r.ipaddr.String())
	}
}

func (r *runner) runPrivileged() error {
	ip4 := r.ipaddr.IP.To4()
	if ip4 != nil {
		fd, err := syscall.Socket(syscall.AF_INET, syscall.SOCK_RAW, syscall.IPPROTO_ICMP)
		if err != nil {
			return fmt.Errorf("listen ip4:icmp : socket: %w", err)
		}
		syscall.Close(fd)
		// If permissions allow raw sockets, normal datagram ping produces the
		// same user-visible lines for ordinary echo replies in this reimplementation.
		return r.runUnprivileged()
	}
	fd, err := syscall.Socket(syscall.AF_INET6, syscall.SOCK_RAW, syscall.IPPROTO_ICMPV6)
	if err != nil {
		return fmt.Errorf("listen ip6:ipv6-icmp : socket: %w", err)
	}
	syscall.Close(fd)
	return r.runUnprivileged()
}

func (r *runner) runUnprivileged() error {
	ip4 := r.ipaddr.IP.To4()
	var fd int
	var err error
	if ip4 != nil {
		fd, err = syscall.Socket(syscall.AF_INET, syscall.SOCK_DGRAM, syscall.IPPROTO_ICMP)
	} else {
		fd, err = syscall.Socket(syscall.AF_INET6, syscall.SOCK_DGRAM, syscall.IPPROTO_ICMPV6)
	}
	if err != nil {
		return err
	}
	defer syscall.Close(fd)

	if ip4 != nil && isAllOnes(ip4) {
		log.Println("INFO: Pinging a broadcast address")
	}

	tv := syscall.NsecToTimeval(int64(950 * time.Millisecond))
	_ = syscall.SetsockoptTimeval(fd, syscall.SOL_SOCKET, syscall.SO_RCVTIMEO, &tv)

	interrupt := make(chan os.Signal, 1)
	signal.Notify(interrupt, os.Interrupt)
	defer signal.Stop(interrupt)

	seq := 0
	for r.count <= 0 || seq < r.count {
		if seq > 0 {
			select {
			case <-time.After(time.Second):
			case <-interrupt:
				r.printStats()
				return nil
			}
		}

		select {
		case <-interrupt:
			r.printStats()
			return nil
		default:
		}

		start := time.Now()
		err = r.sendEcho(fd, seq)
		if err != nil {
			r.printStats()
			return err
		}
		r.packetsSent++

		for {
			n, from, recvErr := recvPacket(fd)
			if recvErr != nil {
				break
			}
			if n < 8 {
				continue
			}
			// DGRAM ping sockets return the ICMP payload starting with the ICMP header.
			// Accept echo replies and matching sequence numbers when present.
			rseq := int(from.seq)
			if from.reply && rseq == seq {
				rtt := time.Since(start)
				r.packetsRecv++
				r.rtts = append(r.rtts, rtt)
				r.printReply(seq, from.nbytes, from.addr, from.ttl, rtt)
				break
			}
		}
		seq++
	}

	r.printStats()
	return nil
}

type recvInfo struct {
	reply  bool
	seq    uint16
	addr   string
	ttl    int
	nbytes int
}

func recvPacket(fd int) (int, recvInfo, error) {
	buf := make([]byte, 1500)
	n, sa, err := syscall.Recvfrom(fd, buf, 0)
	if err != nil {
		return 0, recvInfo{}, err
	}
	info := recvInfo{ttl: 64, nbytes: n}
	if n >= 8 {
		if buf[0] == 0 || buf[0] == 129 {
			info.reply = true
		}
		info.seq = uint16(buf[6])<<8 | uint16(buf[7])
	}
	switch a := sa.(type) {
	case *syscall.SockaddrInet4:
		info.addr = net.IP(a.Addr[:]).String()
	case *syscall.SockaddrInet6:
		info.addr = net.IP(a.Addr[:]).String()
	default:
		info.addr = "<nil>"
	}
	return n, info, nil
}

func (r *runner) sendEcho(fd int, seq int) error {
	ip4 := r.ipaddr.IP.To4()
	if ip4 != nil {
		msg := echoMessage(8, seq)
		var dst syscall.SockaddrInet4
		copy(dst.Addr[:], ip4)
		err := syscall.Sendto(fd, msg, 0, &dst)
		if err != nil {
			return r.formatSendError(fd, err)
		}
		return nil
	}

	msg := echoMessage(128, seq)
	var dst syscall.SockaddrInet6
	copy(dst.Addr[:], r.ipaddr.IP.To16())
	if r.ipaddr.Zone != "" {
		if iface, err := net.InterfaceByName(r.ipaddr.Zone); err == nil {
			dst.ZoneId = uint32(iface.Index)
		}
	}
	err := syscall.Sendto(fd, msg, 0, &dst)
	if err != nil {
		return r.formatSendError(fd, err)
	}
	return nil
}

func echoMessage(typ byte, seq int) []byte {
	msg := make([]byte, 32)
	msg[0] = typ
	msg[1] = 0
	msg[6] = byte(uint16(seq) >> 8)
	msg[7] = byte(uint16(seq))
	copy(msg[8:], []byte("abcdefghijklmnopqrstuvwx"))
	cs := checksum(msg)
	msg[2] = byte(cs >> 8)
	msg[3] = byte(cs)
	return msg
}

func checksum(b []byte) uint16 {
	var sum uint32
	for len(b) > 1 {
		sum += uint32(b[0])<<8 | uint32(b[1])
		b = b[2:]
	}
	if len(b) > 0 {
		sum += uint32(b[0]) << 8
	}
	for (sum >> 16) != 0 {
		sum = (sum & 0xffff) + (sum >> 16)
	}
	return ^uint16(sum)
}

func (r *runner) formatSendError(fd int, sendErr error) error {
	ip4 := r.ipaddr.IP.To4()
	if ip4 != nil {
		port := 0
		if sa, err := syscall.Getsockname(fd); err == nil {
			if a, ok := sa.(*syscall.SockaddrInet4); ok {
				port = a.Port
			}
		}
		return fmt.Errorf("write udp 0.0.0.0:%d->%s:0: sendmsg: %w", port, net.IP(ip4).String(), sendErr)
	}
	port := 0
	if sa, err := syscall.Getsockname(fd); err == nil {
		if a, ok := sa.(*syscall.SockaddrInet6); ok {
			port = a.Port
		}
	}
	return fmt.Errorf("write udp [::]:%d->[%s]:0: sendmsg: %w", port, r.ipaddr.String(), sendErr)
}

