func packetLoss(sent, recv int) string {
	if sent <= 0 {
		return "0"
	}
	loss := float64(sent-recv) / float64(sent) * 100
	if math.Abs(loss-math.Round(loss)) < 1e-9 {
		return strconv.FormatInt(int64(math.Round(loss)), 10)
	}
	return strconv.FormatFloat(loss, 'f', -1, 64)
}

func (r *runner) rttStats() (time.Duration, time.Duration, time.Duration, time.Duration) {
	if len(r.rtts) == 0 {
		return 0, 0, 0, 0
	}
	min := r.rtts[0]
	max := r.rtts[0]
	var total int64
	for _, d := range r.rtts {
		if d < min {
			min = d
		}
		if d > max {
			max = d
		}
		total += int64(d)
	}
	avg := time.Duration(total / int64(len(r.rtts)))
	var variance float64
	mean := float64(total) / float64(len(r.rtts))
	for _, d := range r.rtts {
		diff := float64(d) - mean
		variance += diff * diff
	}
	variance /= float64(len(r.rtts))
	stddev := time.Duration(math.Sqrt(variance))
	return min, avg, max, stddev
}

